import{_ as t,o as e,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"预训练与后训练","description":"理解训练数据、目标函数、梯度更新、预训练、监督微调、偏好优化、安全训练，以及训练与提示的边界。","frontmatter":{"title":"预训练与后训练","description":"理解训练数据、目标函数、梯度更新、预训练、监督微调、偏好优化、安全训练，以及训练与提示的边界。","verified_at":"2026-07-28","sources":["https://arxiv.org/abs/2005.14165","https://arxiv.org/abs/2203.02155","https://arxiv.org/abs/2305.18290","https://web.stanford.edu/~jurafsky/slp3/"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/foundations/model-principles/pretraining-posttraining.md","filePath":"py-agent/foundations/model-principles/pretraining-posttraining.md","lastUpdated":1785291406000}'),n={name:"py-agent/foundations/model-principles/pretraining-posttraining.md"};function o(l,a,h,d,s,p){return e(),r("div",null,[...a[0]||(a[0]=[i(`<h1 id="预训练与后训练" tabindex="-1">预训练与后训练 <a class="header-anchor" href="#预训练与后训练" aria-label="Permalink to &quot;预训练与后训练&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>模型架构规定“怎样计算”，训练决定参数最终实现“什么行为”。预训练从大规模数据中学习通用语言模式和知识关联；后训练用示范、偏好和安全数据塑造模型如何响应指令。二者都会更新参数，而请求时的 Prompt 只改变本次计算的上下文。</p><h2 id="_1-训练在改变什么" tabindex="-1">1. 训练在改变什么 <a class="header-anchor" href="#_1-训练在改变什么" aria-label="Permalink to &quot;1. 训练在改变什么&quot;">​</a></h2><h3 id="_1-1-参数决定输入到输出的函数" tabindex="-1">1.1 参数决定输入到输出的函数 <a class="header-anchor" href="#_1-1-参数决定输入到输出的函数" aria-label="Permalink to &quot;1.1 参数决定输入到输出的函数&quot;">​</a></h3><p>Embedding 矩阵、Attention 投影、前馈层和输出投影都包含可训练参数。训练前，这些参数通常不能产生有用语言；训练后，同一架构因为参数不同，会表现出不同知识、风格和能力。</p><h3 id="_1-2-一次训练步骤" tabindex="-1">1.2 一次训练步骤 <a class="header-anchor" href="#_1-2-一次训练步骤" aria-label="Permalink to &quot;1.2 一次训练步骤&quot;">​</a></h3><p>训练循环可以抽象为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>取一批 Token 序列</span></span>
<span class="line"><span>  -&gt; 前向计算预测分布</span></span>
<span class="line"><span>  -&gt; 目标函数计算预测与目标的差距</span></span>
<span class="line"><span>  -&gt; 反向传播计算每个参数对损失的影响</span></span>
<span class="line"><span>  -&gt; 优化器小幅更新参数</span></span>
<span class="line"><span>  -&gt; 处理下一批数据</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>单个样本不会被简单写入一个参数位置。大量样本通过许多小更新共同塑造分布式表示。</p><h3 id="_1-3-目标函数把-学得好-变成数值" tabindex="-1">1.3 目标函数把“学得好”变成数值 <a class="header-anchor" href="#_1-3-目标函数把-学得好-变成数值" aria-label="Permalink to &quot;1.3 目标函数把“学得好”变成数值&quot;">​</a></h3><p>自回归预训练常使用下一个 Token 的交叉熵损失。若真实 Token 的预测概率低，损失较高；概率高，损失较低。优化器寻求降低训练数据上的平均损失，但低损失不直接等于事实无误、指令安全或业务可用。</p><h2 id="_2-数据决定可学习的分布" tabindex="-1">2. 数据决定可学习的分布 <a class="header-anchor" href="#_2-数据决定可学习的分布" aria-label="Permalink to &quot;2. 数据决定可学习的分布&quot;">​</a></h2><h3 id="_2-1-训练数据提供模式与边界" tabindex="-1">2.1 训练数据提供模式与边界 <a class="header-anchor" href="#_2-1-训练数据提供模式与边界" aria-label="Permalink to &quot;2.1 训练数据提供模式与边界&quot;">​</a></h3><p>数据可能来自网页、书籍、代码、对话和专门构造的样本。模型只能从数据及训练反馈中学习可表达的规律。稀缺、过时、矛盾或低质量数据会限制结果。</p><h3 id="_2-2-数据处理不是附属步骤" tabindex="-1">2.2 数据处理不是附属步骤 <a class="header-anchor" href="#_2-2-数据处理不是附属步骤" aria-label="Permalink to &quot;2.2 数据处理不是附属步骤&quot;">​</a></h3><p>常见处理包括去重、语言和质量筛选、敏感信息处理、许可与来源治理、污染检查和数据配比。去重能减少过度记忆和评测泄漏，配比会影响语言、领域和代码能力，过滤策略也可能同时删除有价值的边缘样本。</p><h3 id="_2-3-训练集、验证集与测试集职责不同" tabindex="-1">2.3 训练集、验证集与测试集职责不同 <a class="header-anchor" href="#_2-3-训练集、验证集与测试集职责不同" aria-label="Permalink to &quot;2.3 训练集、验证集与测试集职责不同&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数据集合</th><th>主要用途</th></tr></thead><tbody><tr><td>训练集</td><td>计算梯度并更新参数</td></tr><tr><td>验证集</td><td>选择超参数、观察过拟合和训练进度</td></tr><tr><td>测试集</td><td>在决策完成后估计未见数据表现</td></tr></tbody></table><p>如果测试题进入训练或被反复用于调参，分数就不再代表独立泛化能力。模型应用自己的评测集也要防止同类污染。</p><h2 id="_3-预训练" tabindex="-1">3. 预训练 <a class="header-anchor" href="#_3-预训练" aria-label="Permalink to &quot;3. 预训练&quot;">​</a></h2><h3 id="_3-1-目标是通用语言建模" tabindex="-1">3.1 目标是通用语言建模 <a class="header-anchor" href="#_3-1-目标是通用语言建模" aria-label="Permalink to &quot;3.1 目标是通用语言建模&quot;">​</a></h3><p>预训练在海量序列上反复预测下一个 Token。为做好预测，模型会学习局部语法、长距离依赖、文体、代码结构、世界知识关联和许多可迁移模式。</p><h3 id="_3-2-能力是共同优化的结果" tabindex="-1">3.2 能力是共同优化的结果 <a class="header-anchor" href="#_3-2-能力是共同优化的结果" aria-label="Permalink to &quot;3.2 能力是共同优化的结果&quot;">​</a></h3><p>预训练数据通常不会为每个能力单独提供标签。翻译、摘要、续写和部分推理行为可能从统一语言建模目标中出现，因为这些模式有助于解释数据。能力不是一个开关，也很难精确归因到单个数据来源。</p><h3 id="_3-3-基础模型不一定会按指令回答" tabindex="-1">3.3 基础模型不一定会按指令回答 <a class="header-anchor" href="#_3-3-基础模型不一定会按指令回答" aria-label="Permalink to &quot;3.3 基础模型不一定会按指令回答&quot;">​</a></h3><p>只做预训练的模型擅长续写分布中的文本。当输入“请总结以下内容”时，它可能续写另一段提示、给出多个答案样例，或模仿数据中的对话格式。理解语言模式与稳定遵循用户意图不是同一训练目标。</p><h2 id="_4-监督微调" tabindex="-1">4. 监督微调 <a class="header-anchor" href="#_4-监督微调" aria-label="Permalink to &quot;4. 监督微调&quot;">​</a></h2><h3 id="_4-1-用示范学习响应形式" tabindex="-1">4.1 用示范学习响应形式 <a class="header-anchor" href="#_4-1-用示范学习响应形式" aria-label="Permalink to &quot;4.1 用示范学习响应形式&quot;">​</a></h3><p>监督微调（SFT）使用“输入或指令 → 期望回答”样本继续训练。它让模型更常采用助手式响应、遵循格式、处理多轮消息，并学习特定任务示范。</p><h3 id="_4-2-sft-仍然是-token-预测" tabindex="-1">4.2 SFT 仍然是 Token 预测 <a class="header-anchor" href="#_4-2-sft-仍然是-token-预测" aria-label="Permalink to &quot;4.2 SFT 仍然是 Token 预测&quot;">​</a></h3><p>实现上通常仍计算回答 Token 的预测损失，只是数据经过人工、模型或规则整理，目标更贴近希望的交互行为。模型不是执行一组硬编码规则，而是提高符合示范模式的输出概率。</p><h3 id="_4-3-示范质量决定行为上限" tabindex="-1">4.3 示范质量决定行为上限 <a class="header-anchor" href="#_4-3-示范质量决定行为上限" aria-label="Permalink to &quot;4.3 示范质量决定行为上限&quot;">​</a></h3><p>互相冲突、含糊或只覆盖简单情况的示范会产生不稳定行为。SFT 可能改善格式和任务习惯，但不能自动修复预训练中缺失的专业知识，也不能提供形式化正确性保证。</p><h2 id="_5-偏好优化" tabindex="-1">5. 偏好优化 <a class="header-anchor" href="#_5-偏好优化" aria-label="Permalink to &quot;5. 偏好优化&quot;">​</a></h2><h3 id="_5-1-偏好数据比较多个回答" tabindex="-1">5.1 偏好数据比较多个回答 <a class="header-anchor" href="#_5-1-偏好数据比较多个回答" aria-label="Permalink to &quot;5.1 偏好数据比较多个回答&quot;">​</a></h3><p>有些质量标准很难写出唯一参考答案，却可以比较“回答 A 是否比回答 B 更有帮助、更诚实或更安全”。偏好数据为这种相对判断提供训练信号。</p><h3 id="_5-2-常见方法有不同训练路径" tabindex="-1">5.2 常见方法有不同训练路径 <a class="header-anchor" href="#_5-2-常见方法有不同训练路径" aria-label="Permalink to &quot;5.2 常见方法有不同训练路径&quot;">​</a></h3><ul><li>RLHF 通常先从人类偏好训练奖励模型，再用强化学习优化语言模型。</li><li>RLAIF 使用 AI 反馈参与偏好标注或评判，但仍需明确原则和质量控制。</li><li>DPO 等直接偏好方法用成对偏好目标更新模型，不必复现完整在线强化学习流程。</li></ul><p>这些名称描述训练范式，不保证某个模型一定使用了相同实现。阅读模型报告时应区分公开方法、供应商实际流程和外界推测。</p><h3 id="_5-3-偏好是分布-不是绝对真理" tabindex="-1">5.3 偏好是分布，不是绝对真理 <a class="header-anchor" href="#_5-3-偏好是分布-不是绝对真理" aria-label="Permalink to &quot;5.3 偏好是分布，不是绝对真理&quot;">​</a></h3><p>标注者会有分歧，质量标准也可能冲突。过度优化“看起来有帮助”可能增加迎合，过度拒绝又会损害正常任务。偏好训练需要与任务评测、安全评测和错误分析共同校准。</p><h2 id="_6-对齐与安全训练" tabindex="-1">6. 对齐与安全训练 <a class="header-anchor" href="#_6-对齐与安全训练" aria-label="Permalink to &quot;6. 对齐与安全训练&quot;">​</a></h2><h3 id="_6-1-对齐塑造可接受行为" tabindex="-1">6.1 对齐塑造可接受行为 <a class="header-anchor" href="#_6-1-对齐塑造可接受行为" aria-label="Permalink to &quot;6.1 对齐塑造可接受行为&quot;">​</a></h3><p>对齐通常指让模型行为更符合人类意图、规则和价值约束。安全训练可能包括拒绝危险请求、保护隐私、降低偏见、识别越权指令和在不确定时表达限制。</p><h3 id="_6-2-行为约束是统计性的" tabindex="-1">6.2 行为约束是统计性的 <a class="header-anchor" href="#_6-2-行为约束是统计性的" aria-label="Permalink to &quot;6.2 行为约束是统计性的&quot;">​</a></h3><p>后训练提高某类行为的概率，并不形成不可绕过的权限系统。新颖输入、长上下文冲突或分布外攻击仍可能导致失败。应用不能把模型拒绝机制当作唯一安全边界。</p><h3 id="_6-3-模型安全与应用安全不同" tabindex="-1">6.3 模型安全与应用安全不同 <a class="header-anchor" href="#_6-3-模型安全与应用安全不同" aria-label="Permalink to &quot;6.3 模型安全与应用安全不同&quot;">​</a></h3><p>模型可以拒绝生成危险文字，但应用仍要控制工具权限、数据访问、网络边界和副作用确认。真正的授权必须由确定性代码和外部系统执行。</p><h2 id="_7-训练阶段的连续关系" tabindex="-1">7. 训练阶段的连续关系 <a class="header-anchor" href="#_7-训练阶段的连续关系" aria-label="Permalink to &quot;7. 训练阶段的连续关系&quot;">​</a></h2><h3 id="_7-1-阶段不是完全隔离的容器" tabindex="-1">7.1 阶段不是完全隔离的容器 <a class="header-anchor" href="#_7-1-阶段不是完全隔离的容器" aria-label="Permalink to &quot;7.1 阶段不是完全隔离的容器&quot;">​</a></h3><p>预训练提供广泛能力，SFT 教交互方式，偏好和安全训练进一步调整行为。后一个阶段可能改善目标行为，也可能损害早先能力，称为能力回退、遗忘或对齐税等现象，需要持续评测。</p><h3 id="_7-2-后训练不会重建所有知识" tabindex="-1">7.2 后训练不会重建所有知识 <a class="header-anchor" href="#_7-2-后训练不会重建所有知识" aria-label="Permalink to &quot;7.2 后训练不会重建所有知识&quot;">​</a></h3><p>少量高质量示范可以显著改变回答习惯，却不等于给模型添加一套完整、可追溯的专业数据库。需要精确知识时，应考虑检索、工具或领域训练，并分别验证。</p><h3 id="_7-3-模型版本变化就是行为依赖变化" tabindex="-1">7.3 模型版本变化就是行为依赖变化 <a class="header-anchor" href="#_7-3-模型版本变化就是行为依赖变化" aria-label="Permalink to &quot;7.3 模型版本变化就是行为依赖变化&quot;">​</a></h3><p>数据、目标、训练步骤或系统模板任一变化，都可能改变输出分布。应用升级模型时必须回归评测，不能只依据参数规模或产品名称判断兼容。</p><h2 id="_8-prompt、检索与微调的边界" tabindex="-1">8. Prompt、检索与微调的边界 <a class="header-anchor" href="#_8-prompt、检索与微调的边界" aria-label="Permalink to &quot;8. Prompt、检索与微调的边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>是否改参数</th><th>适合解决</th><th>不擅长解决</th></tr></thead><tbody><tr><td>Prompt</td><td>否</td><td>本次任务、格式、上下文示例</td><td>永久写入知识、硬安全保证</td></tr><tr><td>检索或工具</td><td>否</td><td>最新、私有、可追踪信息</td><td>自动改变模型固有行为</td></tr><tr><td>监督微调</td><td>是</td><td>稳定风格、任务模式、领域行为</td><td>实时更新、逐条事实引用</td></tr><tr><td>偏好或安全优化</td><td>是</td><td>调整回答偏好和风险行为</td><td>应用权限控制、业务事务一致性</td></tr><tr><td>继续预训练</td><td>是</td><td>大规模领域分布适配</td><td>小样本快速规则修改</td></tr></tbody></table><p>选择方法时先判断问题属于知识可用性、请求指令、行为一致性还是应用控制。把所有问题都归为“Prompt 不够好”或“需要微调”都会选错层级。</p><h2 id="_9-怎样评价训练结果" tabindex="-1">9. 怎样评价训练结果 <a class="header-anchor" href="#_9-怎样评价训练结果" aria-label="Permalink to &quot;9. 怎样评价训练结果&quot;">​</a></h2><h3 id="_9-1-训练损失只是一个信号" tabindex="-1">9.1 训练损失只是一个信号 <a class="header-anchor" href="#_9-1-训练损失只是一个信号" aria-label="Permalink to &quot;9.1 训练损失只是一个信号&quot;">​</a></h3><p>损失下降说明模型更能预测目标数据，不保证真实用户任务变好。还需要独立评测事实、推理、格式、安全、延迟和领域表现。</p><h3 id="_9-2-平均分会隐藏退化" tabindex="-1">9.2 平均分会隐藏退化 <a class="header-anchor" href="#_9-2-平均分会隐藏退化" aria-label="Permalink to &quot;9.2 平均分会隐藏退化&quot;">​</a></h3><p>模型可能总体得分上升，却在某种语言、长上下文或高风险类别上退化。评测应按任务切片，并保留失败样例供人工分析。</p><h3 id="_9-3-训练资料不是应用说明书" tabindex="-1">9.3 训练资料不是应用说明书 <a class="header-anchor" href="#_9-3-训练资料不是应用说明书" aria-label="Permalink to &quot;9.3 训练资料不是应用说明书&quot;">​</a></h3><p>知道模型经历了某种后训练，不足以推断它在你的业务数据上可靠。最终应用结论必须来自版本固定、任务相关的本地评测。</p><h2 id="_10-常见误解" tabindex="-1">10. 常见误解 <a class="header-anchor" href="#_10-常见误解" aria-label="Permalink to &quot;10. 常见误解&quot;">​</a></h2><h3 id="_10-1-把文档放进-prompt-就训练了模型" tabindex="-1">10.1 “把文档放进 Prompt 就训练了模型” <a class="header-anchor" href="#_10-1-把文档放进-prompt-就训练了模型" aria-label="Permalink to &quot;10.1 “把文档放进 Prompt 就训练了模型”&quot;">​</a></h3><p>Prompt 只进入当前上下文，不更新参数。会话结束后是否持久保存由应用系统决定，不是模型训练。</p><h3 id="_10-2-后训练会让答案都正确" tabindex="-1">10.2 “后训练会让答案都正确” <a class="header-anchor" href="#_10-2-后训练会让答案都正确" aria-label="Permalink to &quot;10.2 “后训练会让答案都正确”&quot;">​</a></h3><p>后训练主要塑造行为分布。事实正确、计算正确和权限正确仍需专门数据、工具和验证。</p><h3 id="_10-3-更低训练损失意味着更好的产品" tabindex="-1">10.3 “更低训练损失意味着更好的产品” <a class="header-anchor" href="#_10-3-更低训练损失意味着更好的产品" aria-label="Permalink to &quot;10.3 “更低训练损失意味着更好的产品”&quot;">​</a></h3><p>产品质量由具体任务指标决定。离线损失、通用基准和真实业务成功率不是同一个指标。</p><h2 id="_11-自测" tabindex="-1">11. 自测 <a class="header-anchor" href="#_11-自测" aria-label="Permalink to &quot;11. 自测&quot;">​</a></h2><ol><li>目标函数、反向传播和优化器分别在训练步骤中做什么？</li><li>预训练与监督微调的数据和行为目标有什么差异？</li><li>偏好优化为什么使用相对比较，而不总是唯一答案？</li><li>为什么模型安全训练不能替代应用权限控制？</li><li>Prompt、检索和微调分别适合改变哪一层？</li></ol><p>能够沿“数据 → 目标函数 → 梯度 → 参数 → 行为分布”解释能力形成，并把请求上下文与参数更新分开，就建立了训练阶段的正确边界。</p>`,76)])])}const u=t(n,[["render",o]]);export{b as __pageData,u as default};
